// Builds ../hardware-order.yml from the scripts in this folder: pastes src/common.ps1 where a step says
// "# @@ src/common.ps1 @@", then the _shared libraries with _shared/inject.js.
// Usage: node build.js          rewrite the generated file
//        node build.js --check  exit 1 if the generated file is out of date
// Edit request.ps1, pick.ps1, record.ps1 and common.ps1 (or the libraries in _shared), never the generated .yml.
// Needs js-yaml: npm install in _shared, or set JS_YAML_PATH.
const fs = require('fs');
const path = require('path');
let y;
try { y = require('js-yaml'); } catch { try { y = require(path.join(__dirname, '..', '..', '_shared', 'node_modules', 'js-yaml')); } catch { y = require(process.env.JS_YAML_PATH); } }
const { injectText } = require(path.join(__dirname, '..', '..', '_shared', 'inject.js'));

const here = __dirname;
const root = path.join(here, '..');
const check = process.argv.includes('--check');
const read = (f) => fs.readFileSync(path.join(here, f), 'utf8').replace(/\r\n/g, '\n').trimEnd() + '\n';
const lib = (name) => `# >>> _shared/${name} (generated by _shared/inject.js; edit the source, not this block)\n# <<< _shared/${name}\n`;
const COMMON = '# @@ src/common.ps1 @@';
const withCommon = (s) => s.replace(COMMON, () => read('common.ps1'));
const preamble = (title, lines) =>
  ['# =====================================================================', `#  Order Computer Hardware - ${title}`, ...lines.map((l) => `#  ${l}`),
   '#  Generated from hardware-order/src. Edit the source, then run build.js.',
   '# =====================================================================', "$ErrorActionPreference = 'Stop'", 'Set-StrictMode -Version Latest', ''].join('\n') + '\n';

const requestScript = withCommon(preamble('Read the request', [
  'Read-only. Reads the Order Hardware form answers, the ship-to address and the run settings.',
  'Secrets: HardwareOrder-Vendors (optional, default ingram-micro,td-synnex).',
]) + COMMON + '\n\n# ---------- this step ----------\n' + read('request.ps1'));
const pickScript = withCommon(preamble('Pick the best offers and post the quote', [
  'Orders nothing. With confirm true, adds the quote to the ticket as an internal note, once.',
  "Secrets: PSA-Type and the PSA's own secrets.",
]) + lib('psa.ps1') + COMMON + '\n\n# ---------- this step ----------\n' + read('pick.ps1'));
const recordScript = withCommon(preamble('Record the order on the ticket', [
  'Adds an internal note with the vendor order numbers and a public note for the requester, once.',
  "Secrets: PSA-Type and the PSA's own secrets.",
]) + lib('psa.ps1') + COMMON + '\n\n# ---------- this step ----------\n' + read('record.ps1'));

const RULE = 'Write one short sentence before each tool call and never send an empty message. Make independent tool calls in parallel. Never repeat a secret or key.';
const quoteGoal = [
  'Price the hardware request below at each vendor in its vendors list, using only read tools. This step orders nothing.',
  'For each line: if looks_like_part_number is true, look it up as a manufacturer part number; otherwise search the catalog by its text and pick the closest business model (at most 2 candidates per vendor).',
  'Ingram Micro (vendor ingram-micro): find with im_search_catalog, then price every candidate in ONE im_get_price_availability call with includeAvailability and includePricing true.',
  'TD SYNNEX (vendor td-synnex): price by mfgPN in ONE tds_get_price_availability call for all lines. It has no search, so for a line given only as text, use the manufacturer part number Ingram Micro found for it; if there is none, skip that line at TD SYNNEX.',
  'Return one offer per vendor per candidate with: line, vendor (ingram-micro or td-synnex), partNumber (the vendor SKU), vendorPartNumber (manufacturer part number), description, unitPrice (your price, a number), currency, available (total quantity in stock, a number), authorized (false when the vendor says you cannot buy it, it is discontinued, or price is null), note.',
  'If a vendor fails on every call (401, 403 or not set up), stop calling it and add one line to vendorErrors naming the vendor and the error. Never invent a price, part number or stock figure.',
  'Request: {{ nodes.node-request.output }}',
  'If the request has skip true, return an empty offers list straight away without calling any tool.',
  RULE,
].join('\n');
const quoteOut = {
  type: 'object', additionalProperties: false, required: ['offers', 'vendorErrors', 'summary'],
  properties: {
    summary: { type: 'string' },
    vendorErrors: { type: 'array', items: { type: 'string' } },
    offers: { type: 'array', items: { type: 'object', additionalProperties: false,
      required: ['line', 'vendor', 'partNumber', 'vendorPartNumber', 'description', 'unitPrice', 'currency', 'available', 'authorized', 'note'],
      properties: { line: { type: 'integer' }, vendor: { type: 'string' }, partNumber: { type: 'string' }, vendorPartNumber: { type: 'string' }, description: { type: 'string' },
        unitPrice: { type: 'number' }, currency: { type: 'string' }, available: { type: 'number' }, authorized: { type: 'boolean' }, note: { type: 'string' } } } },
  },
};
const orderGoal = [
  'Place the approved hardware orders in the plan below. Every order tool needs approval, so each order waits for a person to approve it before it runs.',
  'If the plan has skip_order true, return an empty orders list straight away without calling any tool.',
  'For each entry in plan.orders, in turn:',
  '1. Re-check the price of every line with the vendor price and availability tool. If any line now costs more than 5% above its unit_price, or the account can no longer buy it, do not order that vendor: return status not_ordered with the reason.',
  '2. Otherwise propose the order exactly once, using the order po_number as the PO number, the plan ship_to as the ship-to address (name, attention, address1, address2, city, state, zip, country, phone, email), each line quantity and the re-checked price.',
  '   Ingram Micro: im_create_order with customerOrderNumber = po_number, shipToInfo, lines [{customerLineNumber, ingramPartNumber = part_number, quantity, unitPrice}], acceptBackOrder true only if the line is marked backorder.',
  '   TD SYNNEX: tds_submit_po with OrderRequest {PONumber = po_number, DropShipFlag Y, Shipment {ShipTo {AddressName1, AddressLine1, AddressLine2, City, State, ZipCode, Country}, ShipToContact {ContactName, PhoneNumber, EmailAddress}}, Items {Item [{lineNumber, SKU = part_number, OrderQuantity, UnitPrice}]}}.',
  '3. Report status placed (accepted in full), partial (some lines rejected or backordered), rejected (the vendor refused it), denied (the approver denied it) or not_ordered, with the vendor order number and the rejected and backordered lines.',
  'If an order call times out or its result is unclear, look the PO number up with the vendor order search or status tool before anything else, and never propose the same order twice.',
  'Plan: {{ nodes.node-pick.output }}',
  RULE,
].join('\n');
const orderOut = {
  type: 'object', additionalProperties: false, required: ['orders', 'summary'],
  properties: {
    summary: { type: 'string' },
    orders: { type: 'array', items: { type: 'object', additionalProperties: false,
      required: ['vendor', 'po_number', 'status', 'order_number', 'message', 'rejected_lines', 'backordered_lines'],
      properties: { vendor: { type: 'string' }, po_number: { type: 'string' }, status: { type: 'string', enum: ['placed', 'partial', 'rejected', 'denied', 'not_ordered'] },
        order_number: { type: 'string' }, message: { type: 'string' }, rejected_lines: { type: 'array', items: { type: 'string' } }, backordered_lines: { type: 'array', items: { type: 'string' } } } } },
  },
};
const agentNode = (id, name, x, goal, out) => ({
  id, name, type: 'agent', position: { x, y: 120 },
  properties: {
    goal, model: '', allowedExtensions: ['ingram-micro', 'td-synnex'], timeoutSeconds: 900, autoApprove: false,
    inputBindingsJson: '{}', inputSchema: JSON.stringify({ type: 'object', properties: {}, additionalProperties: false }), outputSchema: JSON.stringify(out),
  },
});

const testInput = {
  ticketId: '12345', company: 'Contoso Ltd', requester_email: 'pat.doe@contoso.com', confirm: 'false', vendors: '', psa: '',
  items: '2 x 21MN0001US\n1 x 27 inch USB-C monitor',
  shipName: 'Contoso Ltd', shipAttention: 'Pat Doe', shipAddress1: '1 Example Way', shipAddress2: '', shipCity: 'Springfield', shipState: 'IL', shipZip: '62701', shipCountry: 'US',
  shipPhone: '555-0100', shipEmail: 'pat.doe@contoso.com', neededBy: '', budget: '', notes: '',
};

const wf = {
  automationsWorkflow: 1,
  name: 'Order Computer Hardware',
  description:
    'Turns an Order Hardware request into a priced quote and an approved order: prices each item at Ingram Micro and TD SYNNEX, picks the cheapest ' +
    'offer in stock, adds the quote to the ticket, places the order only after a person approves it, and notes the vendor order numbers on the ticket. ' +
    'Quote only until confirm is true; every order needs approval.',
  definition: {
    schemaVersion: 1,
    activities: [
      { id: 'start', name: 'Start', type: 'start', position: { x: 80, y: 120 }, properties: { webhookEnabled: false } },
      { id: 'node-request', name: 'Read the request', type: 'powershell-script', position: { x: 300, y: 120 },
        properties: { script: requestScript, timeoutSeconds: 60, retryCount: 0, parameters: [], aiExtensions: [], testInput: JSON.stringify(testInput, null, 2) } },
      agentNode('node-quote', 'Price it at each vendor', 520, quoteGoal, quoteOut),
      { id: 'node-pick', name: 'Pick the best offers and post the quote', type: 'powershell-script', position: { x: 740, y: 120 },
        properties: { script: pickScript, timeoutSeconds: 300, retryCount: 0, aiExtensions: [],
          parameters: [{ name: 'req', expression: '{{ nodes.node-request.output }}' }, { name: 'quote', expression: '{{ nodes.node-quote.output }}' }] } },
      agentNode('node-order', 'Place the approved orders', 960, orderGoal, orderOut),
      { id: 'node-record', name: 'Record the order on the ticket', type: 'powershell-script', position: { x: 1180, y: 120 },
        properties: { script: recordScript, timeoutSeconds: 300, retryCount: 0, aiExtensions: [],
          parameters: [{ name: 'plan', expression: '{{ nodes.node-pick.output }}' }, { name: 'result', expression: '{{ nodes.node-order.output }}' }] } },
      { id: 'end', name: 'End', type: 'end', position: { x: 1400, y: 120 } },
    ],
    connections: [['start', 'node-request'], ['node-request', 'node-quote'], ['node-quote', 'node-pick'], ['node-pick', 'node-order'], ['node-order', 'node-record'], ['node-record', 'end']]
      .map(([source, target]) => ({ source, target, sourceHandle: null })),
    startActivityId: 'start',
  },
};

const header = [
  '# CloudRadial AutomationAI - Order Computer Hardware (Ingram Micro and TD SYNNEX extensions, and the PSA ticket).',
  '# Generated by src/build.js. Edit the scripts in src/, not this file.',
  '# Import on Workflows -> Import. See README.md for the extensions, secrets and inputs.',
].join('\n');
const dumped = header + '\n' + y.dump(wf, { lineWidth: -1, noRefs: true });
const { text, blocks } = injectText(dumped, 'hardware-order.yml', new Map());
if (blocks.length !== 2) throw new Error(`expected 2 _shared blocks, got ${blocks.length}`);
const back = y.load(text);
JSON.parse(back.definition.activities.find((a) => a.id === 'node-request').properties.testInput);
if (back.definition.activities[0].properties.webhookEnabled !== false) throw new Error('webhook must ship off');
for (const a of back.definition.activities) {
  const p = a.properties || {};
  if (a.type === 'agent') { JSON.parse(p.outputSchema); JSON.parse(p.inputSchema); if (p.model !== '' || !p.allowedExtensions.length || p.autoApprove !== false) throw new Error(`${a.id}: agent settings`); }
  if (!p.script) continue;
  if (p.script.includes(COMMON)) throw new Error(`${a.id}: common.ps1 marker left in`);
  if (a.id !== 'node-request' && !p.script.includes('function Add-PsaNote')) throw new Error(`${a.id}: psa.ps1 missing`);
  if (new RegExp('[' + String.fromCharCode(0x2013, 0x2014) + ']').test(p.script)) throw new Error(`${a.id}: contains an en or em dash`);
}
const p = path.join(root, 'hardware-order.yml');
const was = fs.existsSync(p) ? fs.readFileSync(p, 'utf8').replace(/\r\n/g, '\n') : null;
const changed = was !== text;
console.log(`hardware-order.yml: ${changed ? (check ? 'OUT OF DATE' : 'updated') : 'current'} (${text.length} bytes)`);
if (changed) { if (check) process.exit(1); fs.writeFileSync(p, text); }
